"""The `offer_cdr` parser (D3 §5.7, §13). Every document is generated by `make_cdr_plan_detail` or edited from it."""

import json
from datetime import UTC, datetime

import pytest

from energatron.adapters.sources.cdr_plan import OFFER_CDR, CdrPlanParser
from energatron.core.errors import InvalidInputError
from energatron.core.ids import offer_snapshot_id
from energatron.core.models.catalog import SourceInfo, SourceType
from energatron.ports.sources import SourceParser
from tests.fixtures.make_sources import make_cdr_plan_detail

NAME = "plan.json"
PLAN = "SYN000001MRE1"


def inspect(data: bytes) -> SourceInfo:
    return OFFER_CDR.inspect(NAME, data)


def reason(data: bytes) -> str:
    with pytest.raises(InvalidInputError) as caught:
        inspect(data)
    value = caught.value.details["reason"]
    assert isinstance(value, str)
    return value


def with_data(**changes: object) -> bytes:
    document = json.loads(make_cdr_plan_detail())
    document["data"].update(changes)
    return json.dumps(document).encode("utf-8")


def test_the_parser_is_a_source_parser_for_offer_cdr_version_1() -> None:
    parser: SourceParser = OFFER_CDR
    assert isinstance(OFFER_CDR, CdrPlanParser)
    assert parser.source is SourceType.OFFER_CDR and parser.version == 1


def test_detect_is_content_only() -> None:
    for data in (make_cdr_plan_detail(), make_cdr_plan_detail(pretty=True), b" \n\t" + make_cdr_plan_detail()):
        detection = OFFER_CDR.detect(NAME, data)
        assert detection is not None and detection.evidence == ("content",)
    assert OFFER_CDR.detect(NAME, b'["planId", "lastUpdated"]') is None
    assert OFFER_CDR.detect(NAME, b'{"planId": "x"}') is None
    assert OFFER_CDR.detect("offer.json", b"") is None


def test_detect_drops_a_bom_and_needs_only_the_head() -> None:
    detection = OFFER_CDR.detect(NAME, b"\xef\xbb\xbf" + make_cdr_plan_detail())
    assert detection is not None and detection.evidence == ("content",)
    big = with_data(description="x" * (70 * 1024))
    assert big.index(b'"lastUpdated"') < 64 * 1024
    head = OFFER_CDR.detect(NAME, big[: 64 * 1024])
    assert head is not None and head.evidence == ("content",)


def test_inspect_a_plan() -> None:
    info = inspect(make_cdr_plan_detail(last_updated="2025-03-01T10:30:00+10:30"))
    assert info.source_ts == datetime(2025, 3, 1, 0, 0, tzinfo=UTC)
    assert info.source_ts.utcoffset() is not None
    data = json.loads(make_cdr_plan_detail(last_updated="2025-03-01T10:30:00+10:30"))["data"]
    assert info.extra == {
        "plan_id": PLAN,
        "fuel_type": "ELECTRICITY",
        "offer_snapshot_id": offer_snapshot_id(PLAN, info.source_ts, data),
        "source_ts_from": "content",
    }
    assert info.coverage is None
    assert info.identifiers == {}
    assert info.extension == ".json"


@pytest.mark.parametrize("fuel", ["ELECTRICITY", "GAS", "DUAL"])
def test_each_fuel_type(fuel: str) -> None:
    assert inspect(make_cdr_plan_detail(fuel_type=fuel)).extra["fuel_type"] == fuel


def test_whitespace_and_links_do_not_change_the_snapshot_id() -> None:
    compact = inspect(make_cdr_plan_detail()).extra["offer_snapshot_id"]
    assert inspect(make_cdr_plan_detail(pretty=True)).extra["offer_snapshot_id"] == compact
    document = json.loads(make_cdr_plan_detail())
    document["links"] = {"self": "https://elsewhere.example.invalid/"}
    assert inspect(json.dumps(document).encode()).extra["offer_snapshot_id"] == compact
    assert inspect(with_data(displayName="Changed")).extra["offer_snapshot_id"] != compact


def test_z_and_fractional_seconds_are_rfc_3339() -> None:
    info = inspect(make_cdr_plan_detail(last_updated="2025-03-01T00:00:00.123Z"))
    assert info.source_ts == datetime(2025, 3, 1, 0, 0, 0, 123000, tzinfo=UTC)


@pytest.mark.parametrize(
    ("data", "expected"),
    [
        (b"{not json", "bad_json"),
        (b'{"data": {"planId": NaN}}', "bad_json"),
        (b"\xff{}", "bad_json"),
        (b'{"data": []}', "no_data"),
        (b'{"meta": {}}', "no_data"),
        (b"[]", "no_data"),
        (with_data(planId="a~b"), "bad_plan_id"),
        (with_data(planId="a b"), "bad_plan_id"),
        (with_data(planId=""), "bad_plan_id"),
        (with_data(planId=7), "bad_plan_id"),
        (with_data(lastUpdated="2025-03-01"), "bad_last_updated"),
        (with_data(lastUpdated="2025-03-01T00:00:00"), "bad_last_updated"),
        (with_data(lastUpdated="2025-02-30T00:00:00Z"), "bad_last_updated"),
        (with_data(lastUpdated=None), "bad_last_updated"),
        (with_data(fuelType="SOLAR"), "bad_fuel_type"),
        (with_data(fuelType=None), "bad_fuel_type"),
    ],
)
def test_malformed(data: bytes, expected: str) -> None:
    assert reason(data) == expected


@pytest.mark.parametrize("value", ["2025-03-01t00:00:00z", "2025-03-01T00:00:00z", "2025-03-01t10:30:00+10:30"])
def test_lowercase_t_and_z_are_rfc_3339_and_normalised(value: str) -> None:
    info = inspect(make_cdr_plan_detail(last_updated=value))
    assert info.source_ts == datetime(2025, 3, 1, 0, 0, tzinfo=UTC)
    upper = inspect(make_cdr_plan_detail(last_updated=value.upper()))
    assert info.extra["offer_snapshot_id"] != upper.extra["offer_snapshot_id"]  # `data` differs in its text


def nested(depth: int) -> bytes:
    """A valid plan-detail response with `data.deep` nested `depth` arrays deep."""
    document = json.loads(make_cdr_plan_detail())
    document["data"]["deep"] = "@"
    return json.dumps(document).encode("utf-8").replace(b'"@"', b"[" * depth + b"]" * depth)


def test_deeply_nested_json_is_bad_json() -> None:
    # Too deep to parse or to hash, depending on the platform's stack: either way `bad_json`, never a crash.
    assert reason(nested(1_000_000)) == "bad_json"


def test_nesting_too_deep_to_parse_is_bad_json(monkeypatch: pytest.MonkeyPatch) -> None:
    def too_deep(*args: object, **kwargs: object) -> object:
        raise RecursionError("maximum recursion depth exceeded")

    monkeypatch.setattr("energatron.adapters.sources.cdr_plan.json.loads", too_deep)
    assert reason(make_cdr_plan_detail()) == "bad_json"


def test_nesting_that_parses_but_is_too_deep_to_hash_is_bad_json(monkeypatch: pytest.MonkeyPatch) -> None:
    # Python parses deeper than it encodes, so a document can parse and still overflow the stack when hashed.
    def too_deep(*args: object) -> str:
        raise RecursionError("Stack overflow while encoding a JSON object")

    monkeypatch.setattr("energatron.adapters.sources.cdr_plan.offer_snapshot_id", too_deep)
    assert reason(make_cdr_plan_detail()) == "bad_json"


def test_moderate_nesting_is_accepted() -> None:
    assert inspect(nested(100)).extra["plan_id"] == PLAN
